@@ -36,6 +36,8 @@ TYPE ERRORS :
 	PUBLISH_NO_SLOT_FREE := 30, 
 	OUT_OFF_DYN_MEMORY := 31,
 	CONNECTION_REFUSED_WHILE_CONNECTING :=32,
-	TIMEOUT_PUBLISH := 33
+	TIMEOUT_PUBLISH := 33,
+	// Tidal Metals fork: MQTTPublish gave up a message the broker answered by closing the connection
+	PUBLISH_REJECTED_BY_BROKER := 34
 );
 END_TYPE
diff --git a/src/MQTT/Function Blocks/MqttPublish.st b/src/MQTT/Function Blocks/MqttPublish.st
index f6a2138..ce8eda6 100644
--- a/src/MQTT/Function Blocks/MqttPublish.st	
+++ b/src/MQTT/Function Blocks/MqttPublish.st	
@@ -31,8 +31,17 @@ VAR_OUTPUT
 	SendTimeout: BOOL;
 	//count of publish send sucsessfull
 	CountSend:ULINT;
+	// Tidal Metals fork: the broker closed the connection within REJECT_WINDOW_MS of this message going out,
+	// REJECT_DISCONNECTS_MAX times in a row, and the message was given up (an MQTT 3.1.1 broker's only answer
+	// to a publish it refuses at QoS 1/2, for example a topic outside the client's ACL on mochi). Without this
+	// the message was resent after every reconnect and the link never stayed up. Cleared by the next send.
+	Rejected : BOOL;

 END_VAR
+VAR CONSTANT
+	REJECT_DISCONNECTS_MAX : UINT := 3;
+	REJECT_WINDOW_MS : UDINT := 2000;
+END_VAR

 VAR
 	requestToSend:BOOL;
@@ -50,6 +59,10 @@ VAR
 	SlotId:UINT;
 	noSendSuccessTimer:ton;
 	TimeoutRising:R_trig;
+	LinkLost : Standard.F_TRIG;		// Tidal Metals fork: BROKER_CONNECTED falling
+	SentMs : UDINT;					// when the client took this message for sending
+	RejectCount : UINT;				// consecutive disconnects right after sending it
+	IsRejectHeld : BOOL;			// given up while send was TRUE: wait for send FALSE before a new request
 END_VAR
 VAR_TEMP
 	PublishReturn:PUBLISH_RETURN;
@@ -61,18 +74,47 @@ SUPER^();
 IF NOT __ISVALIDREF(MQTT_IN_OUT) THEN RETURN; END_IF;
 GVL_MQTT.ProgNum := PROG_NUM.Publish;
 {info 'TODO check this, messeg is repeated!'}
-TriggerEdge(CLK:= send AND MQTT_IN_OUT.BROKER_CONNECTED);
+// Tidal Metals fork: a rejected message is not started again by the reconnect while send is still held
+IF NOT send THEN
+	IsRejectHeld := FALSE;
+END_IF
+TriggerEdge(CLK:= send AND MQTT_IN_OUT.BROKER_CONNECTED AND NOT IsRejectHeld);
+
+// Tidal Metals fork: a broker that refuses a QoS 1/2 publish from an MQTT 3.1.1 client closes the connection; a
+// message that was resent after every reconnect kept the link down for good. Give it up after
+// REJECT_DISCONNECTS_MAX disconnects in a row that follow its sending within REJECT_WINDOW_MS (a lost link is
+// noticed later than that: keep-alive), and report Rejected.
+LinkLost(CLK := MQTT_IN_OUT.BROKER_CONNECTED);
+IF LinkLost.Q AND requestToSend AND WasSendet THEN
+	IF SysTimeCore.SysTimeGetMs() - SentMs < REJECT_WINDOW_MS THEN
+		RejectCount := RejectCount + 1;
+	ELSE
+		RejectCount := 0;
+	END_IF
+	IF RejectCount >= REJECT_DISCONNECTS_MAX THEN
+		requestToSend := FALSE;
+		Rejected := TRUE;
+		IsRejectHeld := TRUE;
+		RejectCount := 0;
+		MQTT_IN_OUT.clientFB.PushError(newError:= ERRORS.PUBLISH_REJECTED_BY_BROKER, text:=Topic^, DoesDisconnect:= FALSE);
+	END_IF
+END_IF

 IF NOT MQTT_IN_OUT.BROKER_CONNECTED THEN
 	//no connection, reset
 	WasSendet := FALSE;
 	MyOutData.PaketData.DUP := FALSE;
+	// Tidal Metals fork: build the message again from the inputs after the reconnect; the topic and payload
+	// lengths were kept from the first build while the pointers read the current strings
+	dataBuild := FALSE;
 END_IF

 done := FALSE;

 IF TriggerEdge.Q THEN
 	requestToSend := TRUE;
+	Rejected := FALSE;
+	RejectCount := 0;
 END_IF

 IF requestToSend AND NOT dataBuild THEN
@@ -109,6 +151,7 @@ IF requestToSend AND NOT WasSendet AND MQTT_IN_OUT.BROKER_CONNECTED THEN
 	PublishReturn:= MQTT_IN_OUT.clientFB.Publish(data:=ADR(MyOutData));
 	IF PublishReturn.success THEN
 		WasSendet := TRUE;
+		SentMs := SysTimeCore.SysTimeGetMs();
 		SlotId:= PublishReturn.SlotId;
 	ELSE
 		WasSendet := FALSE;
@@ -128,7 +171,8 @@ IF MyOutData.PaketData.SendSucsess THEN //sucsses set by HANDLE_MQTT
 	MyOutData.PaketData.SendSucsess := FALSE;
 	//paket away...
 	WasSendet := FALSE;
-	requestToSend := FALSE; 
+	RejectCount := 0;
+	requestToSend := FALSE;
 	done := TRUE;
 	dataBuild := FALSE;
 	MyOutData.PaketData.DUP := FALSE;
